import java.util.*;

public class CF884F {
    static final int A = 26, INF = 0x3f3f3f3f;

    int[] nextArc, arcEdge;
    int arcCnt = 1;

    int addArc(int head, int e) {
        nextArc[arcCnt] = head;
        arcEdge[arcCnt] = e;
        return arcCnt++;
    }

    int[] from, to, cap, orgCost, redCost;
    int edgeCnt;
    int[] head, dist, depth, prevArc;
    int nodeCnt;
    int[] heap, heapPos;
    int heapSize;

    void init(int n, int maxEdge) {
        nodeCnt = 1 + n + A + 1;
        edgeCnt = maxEdge;
        nextArc = new int[1 + edgeCnt * 2];
        arcEdge = new int[1 + edgeCnt * 2];
        from = new int[edgeCnt];
        to = new int[edgeCnt];
        cap = new int[edgeCnt << 1];
        orgCost = new int[edgeCnt];
        redCost = new int[edgeCnt];
        head = new int[nodeCnt];
        dist = new int[nodeCnt];
        depth = new int[nodeCnt];
        prevArc = new int[nodeCnt];
        heap = new int[nodeCnt + 1];
        heapPos = new int[nodeCnt];
        edgeCnt = 0;
    }

    void addEdge(int u, int v, int c, int w) {
        int h = edgeCnt++;
        from[h] = u;
        to[h] = v;
        cap[h << 1] = c;
        orgCost[h] = w;
        head[u] = addArc(head[u], h << 1);
        head[v] = addArc(head[v], h << 1 | 1);
    }

    boolean better(int u, int v) {
        return dist[u] < dist[v] || dist[u] == dist[v] && depth[u] < depth[v];
    }

    int minChild(int i) {
        return (i *= 2) > heapSize ? 0 : (i < heapSize && better(heap[i + 1], heap[i]) ? i + 1 : i);
    }

    void heapUp(int u) {
        int i = heapPos[u], j, v;
        while ((j = i / 2) > 0 && better(u, v = heap[j])) {
            heap[heapPos[v] = i] = v;
            i = j;
        }
        heap[heapPos[u] = i] = u;
    }

    void heapDown(int u) {
        int i = heapPos[u], j, v;
        while ((j = minChild(i)) > 0 && better(v = heap[j], u)) {
            heap[heapPos[v] = i] = v;
            i = j;
        }
        heap[heapPos[u] = i] = u;
    }

    void heapAdd(int u) {
        heap[heapPos[u] = ++heapSize] = u;
    }

    int heapRemove() {
        int u = heap[1], v = heap[heapSize--];
        if (v != u) {
            heapPos[v] = 1;
            heapDown(v);
        }
        heapPos[u] = 0;
        return u;
    }

    boolean dijkstra(int s, int t) {
        Arrays.fill(dist, INF);
        dist[s] = 0;
        heapAdd(s);
        while (heapSize > 0) {
            int u = heapRemove();
            int nd = depth[u] + 1;
            for (int a = head[u]; a != 0; a = nextArc[a]) {
                int eid = arcEdge[a];
                if (cap[eid] <= 0) continue;
                int h = eid >>> 1;
                int v = u ^ from[h] ^ to[h];
                int ndist = dist[u] + ((eid & 1) == 0 ? redCost[h] : -redCost[h]);
                if (ndist < dist[v] || ndist == dist[v] && depth[v] > nd) {
                    if (dist[v] == INF) heapAdd(v);
                    dist[v] = ndist;
                    depth[v] = nd;
                    prevArc[v] = eid;
                    heapUp(v);
                }
            }
        }
        return dist[t] != INF;
    }

    int augment(int s, int t) {
        while (t != s) {
            int eid = prevArc[t];
            int h = eid >>> 1;
            cap[eid]--;
            cap[eid ^ 1]++;
            t ^= from[h] ^ to[h];
        }
        return 1;
    }

    int minCostFlow(int s, int t) {
        for (int h = 0; h < edgeCnt; h++) {
            int u = from[h], v = to[h];
            dist[v] = Math.min(dist[v], dist[u] + orgCost[h]);
        }
        for (int h = 0; h < edgeCnt; h++) {
            int u = from[h], v = to[h];
            redCost[h] = orgCost[h] + dist[u] - dist[v];
        }
        int flowCost = 0;
        while (dijkstra(s, t)) {
            flowCost += augment(s, t);
            for (int h = 0; h < edgeCnt; h++) {
                int u = from[h], v = to[h];
                if (dist[u] != INF && dist[v] != INF)
                    redCost[h] += dist[u] - dist[v];
            }
        }
        int ans = 0;
        for (int h = 0; h < edgeCnt; h++)
            ans += cap[h << 1 | 1] * orgCost[h];
        return ans;
    }

    void run() {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt() / 2;
        int maxEdge = n + n * A + A;
        init(n, maxEdge);
        byte[] s = sc.next().getBytes();
        int[] b = new int[n * 2];
        for (int i = 0; i < n * 2; i++) b[i] = sc.nextInt();

        for (int i = 0; i < n; i++) addEdge(0, 1 + i, 2, 0);
        for (int i = 0; i < n; i++) {
            int j = n * 2 - 1 - i;
            int ai = s[i] - 'a';
            int aj = s[j] - 'a';
            for (int a = 0; a < A; a++) {
                int w;
                if (a == ai && a == aj) w = Math.max(b[i], b[j]);
                else if (a == ai) w = b[i];
                else if (a == aj) w = b[j];
                else w = 0;
                addEdge(1 + i, 1 + n + a, 1, -w);
            }
        }
        int[] cnt = new int[A];
        for (int i = 0; i < n * 2; i++) cnt[s[i] - 'a']++;
        for (int a = 0; a < A; a++)
            addEdge(1 + n + a, nodeCnt - 1, cnt[a], 0);

        System.out.println(-minCostFlow(0, nodeCnt - 1));
    }

    public static void main(String[] args) {
        new CF884F().run();
    }
}
